import json, hashlib
from pathlib import Path
from datetime import datetime, timezone

run = Path(__file__).resolve().parents[1]
home = run.parents[1]
agents = home.parent
protocol_path = Path('math-open-problems/reports/fei-2026-10-11/EXECUTION_PROTOCOL.json')
def read(p):
    return json.loads(p.read_text(encoding='utf-8-sig'))
def write(p, data):
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
def digest(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()
protocol=read(protocol_path)
checks={name:read(run/'out'/f'{name}.json') for name in ['pilot','full','review_pilot','review']}
sources=[
 ('A006','20261023T112840Z-fleet03-A006-posterior-forest-optimization','A006-NORMALIZED-SHARED-TAG-PUSHFORWARD-AND-PAID-CLAUSE-CODE','SHARED_TAG.md'),
 ('A015','20261023T110145Z-fleet03-A015-minterm-barrier-analysis','A015-ONCE-TAGGED-JOINT-DICTIONARY-REFERENCE','JOINT_DICTIONARY_CODE.md')]
